// Szukamy najwyższej i najniższej temperatury dnia oraz ich godzin
const dane = $input.first().json;
const godziny = dane.hourly.time;
const temperatury = dane.hourly.temperature_2m;

let najwyzsza = temperatury[0];
let najnizsza = temperatury[0];
let godzinaNajwyzszej = godziny[0];
let godzinaNajnizszej = godziny[0];

for (let i = 0; i < temperatury.length; i++) {
  if (temperatury[i] > najwyzsza) {
    najwyzsza = temperatury[i];
    godzinaNajwyzszej = godziny[i];
  }

  if (temperatury[i] < najnizsza) {
    najnizsza = temperatury[i];
    godzinaNajnizszej = godziny[i];
  }
}

return [{ json: { najwyzsza, godzinaNajwyzszej, najnizsza, godzinaNajnizszej } }];
